--- Source/PixelArena/ArenaGameMode.h ---
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker is created in BeginPlay with NewObject but stored in a raw, non-UPROPERTY pointer (UArenaScoreTracker* ScoreTracker). The garbage collector therefore purges it (PixelArena-shipping.log 21:05:13: 'Collecting garbage: 412 objects purged'). At 21:05:27 the first goal is scored and AArenaGameMode::OnGoalScored dereferences the dangling pointer, crashing in UArenaScoreTracker::AddPoints with EXCEPTION_ACCESS_VIOLATION (log lines 10-14). Fix applied in Source/PixelArena/ArenaGameMode.h: declare ScoreTracker as UPROPERTY() TObjectPtr<UArenaScoreTracker> so the GC keeps it alive while the GameMode is alive (same pattern as Hud and Palette).",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary is loaded at runtime with LoadObject in AArenaGameMode::BeginPlay and is not referenced by any cooked asset. With bCookAll=False in Config/DefaultGame.ini, only /Game/Maps/Arena (plus its references) and the DirectoriesToAlwaysCook entry /Game/Data/Effects were cooked, so the Palettes directory was never included in the pak. In the packaged build LoadObject fails (log 21:04:12: 'Couldn't find file for package /Game/Data/Palettes/DA_Primary requested by async loading code'), BeginPlay falls back to gray ('Palette is null, using fallback gray'), so the arena renders without colors. Fix applied in Config/DefaultGame.ini: added +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") so the palette is cooked into the pak."
}
